input.command:
mkdir -p src && cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("quote premiums", () => {
  it.todo("empty item list -> premium 5 (only the processing fee)");
  it.todo("plain sword for a newcomer -> 115 (100 base + 10 first insurance + 5 fee)");
  it.todo("plain amulet for a newcomer -> 71 (60 base + 6 first insurance + 5 fee)");
  it.todo("plain staff for a newcomer -> 93 (80 base + 8 first insurance + 5 fee)");
  it.todo("plain potion for a newcomer -> 49 (40 base + 4 first insurance + 5 fee)");
  it.todo("1 rune -> 33 (25 base + 2.5 first insurance + 5 fee = 32.5, rounded up)");
  it.todo("1 moonstone -> 33 (25 base, same as rune)");
  it.todo("2 runes -> 60 (50 base)");
  it.todo("3 runes -> 71 (60 block base)");
  it.todo("4 runes -> 115 (100 base, no block)");
  it.todo("7 runes -> 198 (175 base; 197.5 rounded up in MHPCO's favor)");
  it.todo("2 runes + 1 moonstone -> 88 (75 base, no block across different types)");
  it.todo("3 runes + 3 moonstones -> 137 (120 base, two separate blocks)");
  it.todo("cursed sword for a newcomer -> 165 (100 + 50 curse + 10 first insurance + 5 fee)");
  it.todo("cursed sword + plain amulet -> 231 (160 base + 50 curse on sword only + 16 first insurance + 5 fee)");
  it.todo("sword with enchantment 4 -> 115 (no high-enchantment surcharge)");
  it.todo("sword with exactly enchantment 5 -> 145 (100 + 30 high enchantment + 10 + 5)");
  it.todo("cursed sword with enchantment 5 -> 195 (both surcharges: 100 + 50 + 30 + 10 + 5)");
  it.todo("customer with 1 year -> sword 115 (no loyalty discount)");
  it.todo("customer with exactly 2 years -> sword 95 (100 - 20 loyalty + 10 + 5)");
  it.todo("second quote in a scenario is a follow-up contract -> sword 100 (100 + 10 - 15 + 5)");
  it.todo("long-standing customer's second contract, cursed sword enchantment 7 -> 160");
  it.todo("schema example: 5-year customer, silver amulet enchantment 2 -> 59");
  it.todo("quote with unknown item type 'broomstick' -> throws an Error");
});

describe("claims", () => {
  it.todo("regular steel sword enchantment 3, damage 500 -> payout 400, remainingCap 1600");
  it.todo("rune damage 200 -> payout 100, remainingCap 400 (cap 2 x 250)");
  it.todo("sword 500 + amulet 300 damaged -> payout 600 (deductible per damaged item), remainingCap 2600 (cap 3200)");
  it.todo("steel sword enchantment 9, damage 1000 -> payout 400 (50 % then deductible)");
  it.todo("dragon sword enchantment 9, damage 1000 -> payout 400 (50 % rule wins)");
  it.todo("dragon sword exactly enchantment 8, damage 1000 -> payout 400");
  it.todo("dragon sword enchantment 5, damage 800 -> payout 700 (full reimbursement)");
  it.todo("payout of 350.5 is rounded down -> enchantment 9 sword damage 901 -> payout 350");
  it.todo("two swords, both damaged 500 -> payout 800, remainingCap 3200 (cap 4000)");
  it.todo("cursed sword (premium 165), damage 2500 -> payout 2000, remainingCap 0 (cap from insurance value 1000)");
  it.todo("sword + 3 runes, sword damage 1000 -> payout 900, remainingCap 2600 (cap 3500)");
  it.todo("two successive 1500 claims on a sword -> 1400/600 then 600/0");
  it.todo("claim refers to its policy by quote step index -> amulet on policy 1, damage 200 -> payout 100, remainingCap 1100");
  it.todo("schema example: amulet damage 200 -> payout 100, remainingCap 1100");
  it.todo("damage to an amulet when only a sword is insured -> throws an Error");
  it.todo("damage to an unknown item type -> throws an Error");
  it.todo("two sword damages but only one sword insured -> throws an Error (whole claim rejected)");
  it.todo("damage amount -200 -> throws an Error");
});
EOF
cat > src/cli.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("claim-office CLI", () => {
  it.todo("reads the schema example from stdin and writes {results:[{premium:59},{payout:100,remainingCap:1100}]} to stdout, exit 0");
  it.todo("unknown quote item type -> non-zero exit, error on stderr, no results on stdout");
  it.todo("negative damage amount -> non-zero exit, error on stderr");
});
EOF

