import type { Damage, Item } from "./claim-office.js";

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;
const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
};

function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
}

function payoutCap(items: Item[]): number {
  return CAP_MULTIPLIER * insuranceSum(items);
}

function claimPayout(damages: Damage[]): number {
  return damages.reduce((sum, damage) => sum + damage.amount - DEDUCTIBLE, 0);
}

export function settleClaim(policyItems: Item[], damages: Damage[]): { payout: number; remainingCap: number } {
  const payout = claimPayout(damages);
  return { payout, remainingCap: payoutCap(policyItems) - payout };
}
export function runScenario(scenario: Scenario): ScenarioResults {
  const policies = new Map<number, Item[]>();
  return {
    results: scenario.steps.map((step, index) => {
      if (step.op === "claim") {
        return settleClaim(policies.get(step.policy) ?? [], step.incident.damages);
      }
      policies.set(index, step.items);
      const hasEarlierQuote = index > 0;
      return { premium: quotePremium(step.items, scenario.customer, hasEarlierQuote) };
    }),
  };
}

